namespace VirtualMonitorsUniverse.Server;

/// <summary>
/// Progressive enhancement for the monitor Properties page. The existing form and
/// handlers remain authoritative; this layer only reorganizes them into the modern
/// workspace while preserving the global VMU navigation and established behavior.
/// </summary>
internal static class MonitorPropertiesWebEnhancement
{
    public const string Content = """
<style>
.monitorPropertiesWorkspace{max-width:1420px;margin:22px auto;padding:0 22px}.monitorPropertiesWorkspace>.page{max-width:none;margin:0;padding:0}.monitorPropertiesWorkspace .properties{max-width:none;background:#fff;border:1px solid #d9e0e8;border-radius:14px;box-shadow:0 10px 32px #1f293714;overflow:hidden}.mpHeader{display:flex;align-items:center;gap:20px;padding:18px 24px;border-bottom:1px solid #e1e6ec;background:linear-gradient(180deg,#fff,#fbfcfe)}.mpHeaderAvatar{width:118px;height:78px;display:flex;align-items:center;justify-content:center;border-radius:9px;background:#eef5ff;overflow:hidden;flex:0 0 auto}.mpHeaderAvatar img{width:72px;height:72px;object-fit:contain}.mpHeaderText{min-width:0}.mpHeaderText h1{margin:0 0 8px;font-size:25px}.mpMeta{display:flex;gap:14px;align-items:center;flex-wrap:wrap;color:#4f5e70}.mpMeta span+span{border-left:1px solid #d8dee7;padding-left:14px}.mpBody{display:grid;grid-template-columns:230px minmax(0,1fr);min-height:610px}.mpSidebar{padding:18px 12px;border-right:1px solid #e1e6ec;background:#fbfcfd}.mpTab{display:flex;width:100%;align-items:center;gap:11px;border:0;background:transparent;color:#263445;padding:12px 14px;border-radius:9px;text-align:left;min-height:46px;cursor:pointer}.mpTab:hover,.mpTab:focus-visible{background:#edf4ff;outline:none}.mpTab.active{background:#1677ed;color:#fff;font-weight:600}.mpTabIcon{width:24px;text-align:center;font-size:18px}.mpTab.disabled{opacity:.5;cursor:not-allowed}.mpContent{padding:22px 28px 96px;position:relative;min-width:0}.mpPane{display:none}.mpPane.active{display:block}.mpPane h2{margin:0 0 5px;font-size:23px}.mpPaneIntro{margin:0 0 20px;color:#647386}.mpFields{max-width:720px}.mpFields>label,.mpPane fieldset>label{display:grid;grid-template-columns:170px minmax(0,1fr);gap:14px;margin:12px 0;align-items:center}.mpPane fieldset{max-width:760px}.mpPane input,.mpPane select{width:100%;min-height:38px}.mpPane #caps{display:flex;gap:18px;flex-wrap:wrap;margin:14px 0}.mpPane #caps label{display:flex;align-items:center;gap:7px}.mpPane #caps input{width:auto;min-height:auto}.mpImmediate{display:flex;align-items:center;gap:8px;margin:18px 0 0}.mpImmediate input{width:auto;min-height:auto}.mpImmediate.disabled{opacity:.5}.mpAvatarLayout{display:grid;grid-template-columns:190px minmax(0,1fr);gap:28px;align-items:start}.mpAvatarCurrent{border:1px solid #d8e0ea;border-radius:12px;padding:14px;background:#f8fafc;text-align:center}.mpAvatarCurrent b{display:block;margin-bottom:10px}.mpAvatarCurrent img{width:150px;height:150px;object-fit:contain}.mpAvatarGallery .avatarpicker{position:static}.mpAvatarGallery .avatarcurrent{display:none!important}.mpAvatarGallery .avatargrid{position:static!important;display:grid!important;grid-template-columns:repeat(auto-fill,minmax(92px,1fr))!important;gap:10px!important;padding:0!important;border:0!important;box-shadow:none!important;background:transparent!important}.mpAvatarGallery .avatargrid button{width:100%!important;height:92px!important;padding:5px!important;border:2px solid transparent!important;background:#f5f7fa!important;border-radius:11px!important}.mpAvatarGallery .avatargrid button:hover{background:#edf4ff!important}.mpAvatarGallery .avatargrid button.selected{outline:none!important;border-color:#1677ed!important;box-shadow:0 0 0 2px #1677ed22}.mpAvatarGallery [data-animal] img,.mpAvatarGallery .customtile img{width:80px!important;height:80px!important;object-fit:contain!important;border-radius:8px}.mpAvatarGallery .avataradd{font-size:38px!important;color:#526174!important}.mpFooter{position:absolute;left:0;right:0;bottom:0;display:flex;justify-content:space-between;gap:12px;align-items:center;padding:14px 24px;border-top:1px solid #e1e6ec;background:#fff}.mpFooterLeft,.mpFooterRight{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.mpFooter .buttonlink,.mpFooter button{min-height:42px;padding:9px 18px}.mpFooter #save{min-width:112px}.mpError{margin:0 0 12px}.mpHealthCard{max-width:760px;border:1px solid #d9e0e8;border-radius:10px;padding:18px;background:#f8fafc}.monitorPropertiesWorkspace .page>h1{display:none}.monitorPropertiesWorkspace .page>.error{display:none}.monitorPropertiesWorkspace .properties>.actions{display:none}.monitorPropertiesWorkspace .properties>label,.monitorPropertiesWorkspace .properties>fieldset{display:none}
@media(max-width:850px){.monitorPropertiesWorkspace{padding:0 10px;margin:12px auto}.mpHeader{padding:14px}.mpHeaderAvatar{width:82px;height:64px}.mpHeaderAvatar img{width:58px;height:58px}.mpBody{grid-template-columns:1fr}.mpSidebar{display:flex;overflow-x:auto;border-right:0;border-bottom:1px solid #e1e6ec;padding:8px}.mpTab{width:auto;white-space:nowrap;flex:0 0 auto}.mpContent{padding:18px 16px 110px}.mpAvatarLayout{grid-template-columns:1fr}.mpAvatarCurrent{display:none}.mpAvatarGallery .avatargrid{grid-template-columns:repeat(auto-fill,minmax(76px,1fr))!important}.mpAvatarGallery .avatargrid button{height:76px!important}.mpAvatarGallery [data-animal] img,.mpAvatarGallery .customtile img{width:66px!important;height:66px!important}.mpFields>label,.mpPane fieldset>label{grid-template-columns:1fr;gap:5px}.mpFooter{padding:10px 14px}.mpFooterLeft #connect,.mpFooterLeft #disconnect{display:none}}
</style>
<script>
(() => {
  const form=document.getElementById('f');if(!form||!location.pathname.startsWith('/monitors/')||location.pathname==='/monitors/new')return;
  const page=form.closest('.page');if(!page||page.dataset.vmuPropertiesLayout)return;page.dataset.vmuPropertiesLayout='1';
  const originalError=page.querySelector('#error');const labels=[...form.children].filter(x=>x.tagName==='LABEL');const fieldsets=[...form.querySelectorAll(':scope > fieldset')];const actions=form.querySelector(':scope > .actions');
  const byControl=id=>labels.find(x=>x.querySelector('#'+id));const titleRow=byControl('title'),nameRow=byControl('name'),avatarRow=byControl('res')?.previousElementSibling,resRow=byControl('res'),hzRow=byControl('hz'),orientationRow=byControl('portrait');const remote=fieldsets.find(x=>x.querySelector('#remote'));const windows=fieldsets.find(x=>x.querySelector('#wd'));const health=fieldsets.find(x=>x.querySelector('#hs'));
  if(!titleRow||!nameRow||!avatarRow||!resRow||!hzRow||!orientationRow||!remote||!windows||!health||!actions)return;
  const workspace=document.createElement('div');workspace.className='monitorPropertiesWorkspace';page.parentNode.insertBefore(workspace,page);workspace.appendChild(page);
  const header=document.createElement('div');header.className='mpHeader';header.innerHTML='<div class="mpHeaderAvatar" id="mpHeaderAvatar"></div><div class="mpHeaderText"><h1 id="mpMonitorTitle">Monitor Properties</h1><div class="mpMeta"><span id="mpConnection"></span><span id="mpResolution"></span><span id="mpWindows"></span></div></div>';form.insertBefore(header,form.firstChild);
  const body=document.createElement('div');body.className='mpBody';const side=document.createElement('aside');side.className='mpSidebar';const content=document.createElement('main');content.className='mpContent';body.append(side,content);form.insertBefore(body,actions);
  const panes={};function pane(id,title,intro){const p=document.createElement('section');p.className='mpPane';p.dataset.pane=id;p.innerHTML='<h2>'+title+'</h2>'+(intro?'<p class="mpPaneIntro">'+intro+'</p>':'');content.appendChild(p);panes[id]=p;return p;}function tab(id,icon,text,disabled=false){const b=document.createElement('button');b.type='button';b.className='mpTab'+(disabled?' disabled':'');b.dataset.tab=id;b.disabled=disabled;b.innerHTML='<span class="mpTabIcon">'+icon+'</span><span>'+text+'</span>';if(!disabled)b.onclick=()=>activate(id);side.appendChild(b);}function activate(id){side.querySelectorAll('.mpTab').forEach(x=>x.classList.toggle('active',x.dataset.tab===id));content.querySelectorAll('.mpPane').forEach(x=>x.classList.toggle('active',x.dataset.pane===id));}
  tab('general','⚙','General');tab('connection','↗','Connection');tab('display','▣','Display');tab('position','⌖','Position');tab('capabilities','◇','Capabilities');tab('audio','◖','Audio',true);tab('avatar','●','Avatar');tab('health','♡','Health');
  const general=pane('general','General','Monitor identity and friendly name.');const gf=document.createElement('div');gf.className='mpFields';gf.append(titleRow,nameRow);general.appendChild(gf);
  const connection=pane('connection','Remote Access','Presentation and collaboration access settings.');connection.appendChild(remote);
  const display=pane('display','Display','Resolution, refresh rate and orientation.');const df=document.createElement('div');df.className='mpFields';df.append(resRow,hzRow,orientationRow);display.appendChild(df);
  const position=pane('position','Windows Position','Current Windows display identity and desktop position.');position.appendChild(windows);
  const capabilities=pane('capabilities','Collaboration Capabilities','Choose which interactive features this monitor accepts.');const caps=remote.querySelector('#caps');if(caps)capabilities.appendChild(caps);
  const immediateLabel=document.createElement('label');immediateLabel.className='mpImmediate';immediateLabel.innerHTML='<input id="mouseImmediate" type="checkbox"> Mouse Passthrough Immediately';capabilities.appendChild(immediateLabel);const mouseImmediate=immediateLabel.querySelector('#mouseImmediate');
  const avatar=pane('avatar','Avatar','Choose a large visual identity for this monitor. The same avatar is used in VMU navigation and monitor lists.');const picker=avatarRow.querySelector('.avatarpicker');const avLayout=document.createElement('div');avLayout.className='mpAvatarLayout';avLayout.innerHTML='<div class="mpAvatarCurrent"><b>Current avatar</b><div id="mpAvatarPreview"></div></div><div class="mpAvatarGallery"></div>';avatar.appendChild(avLayout);if(picker)avLayout.querySelector('.mpAvatarGallery').appendChild(picker);avatarRow.remove();
  const healthPane=pane('health','Monitor Health','Current VMU and Windows monitor status.');health.classList.add('mpHealthCard');healthPane.appendChild(health);
  const footer=document.createElement('div');footer.className='mpFooter';const left=document.createElement('div');left.className='mpFooterLeft';const right=document.createElement('div');right.className='mpFooterRight';const save=actions.querySelector('#save'),cancel=actions.querySelector('a[href="/monitors"]'),connect=actions.querySelector('#connect'),disconnect=actions.querySelector('#disconnect'),terminal=actions.querySelector('#terminal'),uninstall=actions.querySelector('#uninstall');[connect,disconnect,terminal,uninstall].forEach(x=>x&&left.appendChild(x));[cancel,save].forEach(x=>x&&right.appendChild(x));footer.append(left,right);content.appendChild(footer);actions.remove();
  if(originalError){originalError.classList.add('mpError');content.insertBefore(originalError,content.firstChild);originalError.style.display='block';}

  let settings=null,vmuId='',propertyBaseline='',immediateBaseline=false,ready=false;
  function propertyState(){const p=document.querySelector('.avatarpicker');return JSON.stringify([document.getElementById('title')?.value,document.getElementById('name')?.value,document.getElementById('res')?.value,document.getElementById('hz')?.value,document.getElementById('portrait')?.value,document.getElementById('remote')?.value,document.getElementById('security')?.value,document.getElementById('clip')?.checked,document.getElementById('mouse')?.checked,document.getElementById('key')?.checked,p?.dataset.kind,p?.dataset.selected,!!p?._file]);}
  function updateImmediateAvailability(){const enabled=document.getElementById('mouse')?.checked===true;mouseImmediate.disabled=!enabled;immediateLabel.classList.toggle('disabled',!enabled);if(!enabled)mouseImmediate.checked=false;}
  function updateSave(){if(!ready)return;save.disabled=propertyState()===propertyBaseline&&mouseImmediate.checked===immediateBaseline;}
  async function loadImmediate(){try{const [monitor,currentSettings]=await Promise.all([fetch(location.pathname.replace('/monitors/','/api/monitors/'),{cache:'no-store'}).then(r=>r.ok?r.json():null),fetch('/api/settings',{cache:'no-store'}).then(r=>r.ok?r.json():null)]);settings=currentSettings;vmuId=monitor?.configuration?.vmuId||'';const map=settings?.terminalInput?.mousePassthroughImmediatelyByMonitor||{};mouseImmediate.checked=vmuId?map[vmuId]===true:false;immediateBaseline=mouseImmediate.checked;updateImmediateAvailability();setTimeout(()=>{propertyBaseline=propertyState();ready=true;updateSave();},180);}catch{setTimeout(()=>{propertyBaseline=propertyState();ready=true;updateSave();},180);}}
  async function saveImmediate(){if(!settings||!vmuId)return;settings.terminalInput=settings.terminalInput||{};settings.terminalInput.mousePassthroughImmediatelyByMonitor=settings.terminalInput.mousePassthroughImmediatelyByMonitor||{};if(mouseImmediate.checked)settings.terminalInput.mousePassthroughImmediatelyByMonitor[vmuId]=true;else delete settings.terminalInput.mousePassthroughImmediatelyByMonitor[vmuId];const response=await nativeFetch('/api/settings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(settings)});if(!response.ok)throw new Error((await response.json()).error||'Could not save Terminal mouse settings.');immediateBaseline=mouseImmediate.checked;}
  const nativeFetch=window.fetch.bind(window);window.fetch=async(inputArg,init)=>{const response=await nativeFetch(inputArg,init);try{const url=typeof inputArg==='string'?inputArg:inputArg?.url;const path=url?new URL(url,location.href).pathname:'';if(response.ok&&String(init?.method||'GET').toUpperCase()==='PUT'&&path.startsWith('/api/monitors/'))await saveImmediate();}catch(error){document.getElementById('error').textContent=error.message;throw error;}return response;};

  function refreshChrome(){const t=document.getElementById('title')?.value||'Monitor';document.getElementById('mpMonitorTitle').textContent='Monitor Properties – '+t;const connected=!document.getElementById('disconnect')?.disabled;document.getElementById('mpConnection').innerHTML='<span class="dot '+(connected?'on':'')+'"></span> '+(connected?'Connected':'Disconnected');document.getElementById('mpResolution').textContent=(document.getElementById('res')?.value||'')+' @ '+(document.getElementById('hz')?.value||'—')+' Hz';document.getElementById('mpWindows').textContent=document.getElementById('wd')?.value||'';const picker=document.querySelector('.avatarpicker'),preview=document.getElementById('mpAvatarPreview'),head=document.getElementById('mpHeaderAvatar');if(picker&&preview){const selected=picker.querySelector('[data-animal].selected img')||picker.querySelector('.customtile.selected img')||picker.querySelector('.avatarcurrent img');if(selected){preview.innerHTML='<img src="'+selected.src+'" alt="">';head.innerHTML='<img src="'+selected.src+'" alt="">';}}}
  form.addEventListener('input',()=>setTimeout(()=>{refreshChrome();updateImmediateAvailability();updateSave();},0));form.addEventListener('change',()=>setTimeout(()=>{refreshChrome();updateImmediateAvailability();updateSave();},0));form.addEventListener('avatar-changed',()=>setTimeout(()=>{refreshChrome();updateSave();},0));new MutationObserver(refreshChrome).observe(form,{subtree:true,attributes:true,attributeFilter:['disabled','class']});activate('avatar');setTimeout(refreshChrome,120);loadImmediate();
})();
</script>
""";
}
